  local!isNewVersion: if(
    a!isNullOrEmpty(ri!coreAsk.createdOn),
    true,
    if(
      todatetime(ri!coreAsk.createdOn) > #"_a-0000ebac-bfa0-8000-9c55-011c48011c48_12888338",
      true,
      false
    )
  ),
  {
    #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3781239"(
      reportName: "ASK Home",
      report: #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3725690",
      recordName: index(
        split(ri!coreAsk.dppGroup, "–"),
